#include <iostream>
#include <vector>
#include <cmath>
#include <cassert>
#include <cstring>

using namespace std;

const long long MOD = 1000000007;

struct Matrix {
    int size;
    long long mat[33][33];

    Matrix(int n = 0, long long diagVal = 0) : size(n) {
        memset(mat, 0, sizeof(mat));
        for (int i = 0; i < n; ++i) {
            mat[i][i] = diagVal;
        }
    }

    Matrix operator*(const Matrix& other) const {
        assert(size == other.size);
        Matrix result(size);
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                for (int k = 0; k < size; ++k) {
                    result.mat[i][k] = (result.mat[i][k] + mat[i][j] * other.mat[j][k]) % MOD;
                }
            }
        }
        return result;
    }

    Matrix& operator*=(const Matrix& other) {
        *this = *this * other;
        return *this;
    }

    Matrix pow(int exponent) const {
        Matrix result(size, 1);
        Matrix base = *this;
        int e = exponent;
        while (e > 0) {
            if (e & 1) result *= base;
            base *= base;
            e >>= 1;
        }
        return result;
    }
};

int main() {
    long long n;
    int k;
    cin >> n >> k;
    if (n <= k) {
        cout << (1LL << n) % MOD << "\n";
        return 0;
    }

    int logN = int(log(n + 0.0) / log(k + 0.0)) + 2;

    Matrix shift(k + 1, 1);
    for (int j = 0; j < k; ++j) {
        shift.mat[j][j] = 0;
        shift.mat[(j + 1) % k][j] = 1;
    }

    vector<Matrix> blocks(logN);
    blocks[0] = Matrix(k + 1, 1);
    for (int i = 1; i <= k; ++i) {
        blocks[0].mat[0][i] = 1;
    }

    for (int i = 1; i < logN; ++i) {
        blocks[i] = (blocks[i - 1] * shift).pow(k);
    }

    int index = 0;
    long long length = 1;
    while (n / length >= k) {
        ++index;
        length *= k;
    }

    Matrix m(k + 1, 1);
    long long remaining = n;
    long long currentLen = length;
    int i = index;

    while (remaining > 0) {
        if (currentLen <= remaining) {
            int x = int(remaining / currentLen);
            m *= (blocks[i] * shift).pow(x);
            remaining -= currentLen * x;
        }
        --i;
        currentLen /= k;
    }

    long long answer = 0;
    for (int i = 0; i <= k; ++i) {
        answer = (answer + m.mat[i][k]) % MOD;
    }
    cout << answer << "\n";

    return 0;
}
